const{Vec3}=require('vec3');const table=bot.blockAt(new Vec3(6,66,82));console.log('START',bot.entity.position,bot.health,bot.food,bot.inventory.items().map(i=>[i.name,i.count]));if(bot.entity.position.distanceTo(new Vec3(6.5,67,82.5))>.3||Math.abs(bot.health-2.1666641235351562)>.01||table?.name!=='crafting_table')throw Error('freshbody/table failed');await bot.lookAt(table.position.offset(.5,.99,.5),true);const c=bot.blockAtCursor(4.5);if(!c?.position.equals(table.position)||c.face!==1)throw Error('table actualface hidden');let w;try{w=await bot.openBlock(table);console.log('TABLE_OPEN',w.id,w.type,w.title,bot.health);await bot.closeWindow(w);w=null;console.log('TABLE_CLOSED',bot.currentWindow===null,bot.health);}finally{if(w)await bot.closeWindow(w);}
for(const name of ['fishing_rod','wooden_sword','stick','furnace','bow']){const all=bot.recipesAll(bot.registry.itemsByName[name].id,null,table);const summaries=all.map(r=>({requiresTable:r.requiresTable,result:r.result,ingredients:r.delta.filter(d=>d.count<0).map(d=>({name:bot.registry.items[d.id]?.name,id:d.id,count:-d.count}))}));let chosen=summaries.filter(r=>!['wooden_sword','stick'].includes(name)||r.ingredients.some(i=>i.name==='oak_planks'));console.log('RECIPE_BUNDLE',name,JSON.stringify({variants:all.length,chosen,currentlyAvailable:bot.recipesFor(bot.registry.itemsByName[name].id,null,1,table).length}));}
console.log('ENDING',bot.entity.position,bot.health,bot.food,bot.currentWindow,bot.inventory.items().map(i=>[i.name,i.count]));
